css:
.display-switcher {
  margin: 0 auto;
  position: relative;
}

.display-switcher .switch-item {
  width: auto;
  height: 100%;
  max-height: 100vh;
  aspect-ratio: 9/16;
  margin: 0 auto;
  position: relative;
}

.display-switcher .switch-item.is-hidden {
  display: none !important;
}

.display-switcher .switch-item a,
.display-switcher .switch-item [data-switch-to] {
  cursor: pointer;
  transition: opacity 0.2s;
}

.display-switcher .switch-item a:hover,
.display-switcher .switch-item [data-switch-to]:hover {
  opacity: 0.8;
}

.display-switcher .switch-item .mv {
  width: 100%;
  height: 100%;
}

.display-switcher .switch-item .mv img,
.display-switcher .switch-item .mv video {
  width: 100%;
  height: 100% !important;
  object-fit: contain;
  vertical-align: bottom;
  margin: 0 auto !important;
}

.display-switcher .switch-item .btn-next {
  width: 60%;
  max-width: 320px;
  background: none;
  border: none;
  outline: none;
  padding: 0;
  appearance: none;
  position: absolute;
  top: 10px;
  right: 10px;
}

/* 全体の設定 */
.map__area {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 600px;
  /* 外側の余白｜上下｜左右（センタリング）｜ */
  margin: 0 auto;
}



/* 日本地図DOM */
.japan_map {
  position: relative;
  box-sizing: border-box;
  /* 外側の余白 */
  margin: 0 auto;
  display: table;
  /* 背景色 */
  background-color: #fff;
}



/* 日本地図画像（スマホ対応用） */
.japan_map img {
  /*　最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /* 線｜太さ｜ */
  border: 0;
  /* chromeの画像ボケ対策 */
  -webkit-backface-visibility: hidden;
}



/* 日本地図ボタン */
.japan_map .area_btn {
  position: absolute;
  /* 表示順番 */
  z-index: 1;
  box-sizing: border-box;
  /* カーソルが対象物に触れた時に指マークになる */
  cursor: pointer;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #cccccc;
  /* 角丸 */
  border-radius: 5px;
  overflow: hidden;
}



/* ボタン画像 */
.japan_map .area_btn img {
  /* 横幅 */
  width: 100%;
}



/* ボタン配置（使用する日本地図画像により微調整）*/
/* 北海道 */
.japan_map .area_btn.area1 {
  /* 表示位置（上基準） */
  top: 11%;
  /* 表示位置（右基準） */
  right: 8%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0s infinite;
}



/* 東北 */
.japan_map .area_btn.area2 {
  /* 表示位置（上基準） */
  top: 32%;
  /* 表示位置（右基準） */
  right: 12.2%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0.5s infinite;
}



/* 関東 */
.japan_map .area_btn.area3 {
  /* 表示位置（上基準） */
  top: 60%;
  /* 表示位置（右基準） */
  right: 12%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 1s infinite;
}



/* 北陸・信越 */
.japan_map .area_btn.area4 {
  /* 表示位置（上基準） */
  top: 40%;
  /* 表示位置（右基準） */
  right: 35%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 1.5s infinite;
}



/* 中部 */
.japan_map .area_btn.area5 {
  /* 表示位置（上基準） */
  top: 75%;
  /* 表示位置（右基準） */
  right: 29%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0.3s infinite;
}



/* 近畿 */
.japan_map .area_btn.area6 {
  /* 表示位置（上基準） */
  top: 60%;
  /* 表示位置（左基準） */
  left: 40%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0s infinite;
}



/* 中国 */
.japan_map .area_btn.area7 {
  /* 表示位置（上基準） */
  top: 52%;
  /* 表示位置（左基準） */
  left: 22%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 1.75s infinite;
}



/* 四国 */
.japan_map .area_btn.area8 {
  /* 表示位置（上基準） */
  top: 76%;
  /* 表示位置（左基準） */
  left: 27%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0.75s infinite;
}



/* 九州・沖縄 */
.japan_map .area_btn.area9 {
  /* 表示位置（上基準） */
  top: 68%;
  /* 表示位置（左基準） */
  left: 5%;
  /* 横幅 */
  width: 16%;
  /* アニメーション */
  animation: puyo-anim 2s 0s infinite;
}



/* オーバーレイ */
.japan_map .area_overlay {
  /* 初期非表示 */
  display: none;
  position: absolute;
  /* 表示順番 */
  z-index: 2;
  /* 表示位置（上基準） */
  top: 0;
  /* 表示位置（左基準） */
  left: 0;
  /* 最小幅 */
  min-width: 100%;
  /* 最小高さ */
  min-height: 100%;
  /* 横幅 */
  width: auto;
  /* 高さ */
  height: auto;
  /* 背景色 */
  background-color: #111;
  /* 透明度 */
  opacity: 0.5;
  /* カーソルが対象物に触れた時に指マークになる */
  cursor: pointer;
}



/* 選択前は表示を隠す */
.japan_map .pref_area {
  display: none;
}



/* 地域毎の都道府県リスト */
.japan_map .pref_list {
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 50%;
  transform: translateY(-50%) translateX(-50%);
  /* 表示順番 */
  z-index: 3;
  box-sizing: border-box;
  display: flex;
  flex-wrap: wrap;
  /* 横幅 */
  width: 90%;
  /* 背景色 */
  background-color: #FFF;
}

 .japan_map .pref_list>a {
  box-sizing: border-box;
  /* 横幅 */
  width: 50%;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #CCC;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の位置 */
  text-align: center;
  /* 内側の余白 */
  padding: 0.5em;
  /* カーソルが対象物に触れた時に指マークになる */
  cursor: pointer;
  /* 文字色 */
  color: #066dc4;
  /* 下線 */
  text-decoration: none;
  /* 背景色 */
  background: #fff;
  /* アニメーションの対象と速さ */
  transition: background 0.2s;
}

 .japan_map .pref_list>a:hover {
  /* 背景色 */
  background: #d7edee;
}



/* 北海道など1つしか表示されない地域の設定 */
.japan_map .pref_list.contentOne {
  /* 横幅 */
  width: 45%;
}

 .japan_map .pref_list.contentOne a {
  /* 横幅 */
  width: 100%;
}

/* ボタンアニメーション */
@keyframes puyo-anim {

  0%,
  65% {
    transform: scale(1) translate(0%, 0%);
  }

  75% {
    transform: scale(0.96, 1.04) translate(0%, 0%);
  }

  85% {
    transform: scale(1) translate(0%, 0%);
  }

  95% {
    transform: scale(1.05, 0.9) translate(0%, -10%);
  }

  100% {
    transform: scale(1) translate(0%, 0%);
  }
}

 .widget-container * {
  box-sizing: border-box;
  margin-block: -0.175em;
}

 .shaking {
  display: inline-block;
  animation: shaking 100ms linear infinite;
}

@keyframes shaking {
  0% {
    transform: translate(0px, 0px) rotateZ(0deg);
  }

  25% {
    transform: translate(2px, 2px) rotateZ(1deg);
  }

  50% {
    transform: translate(0px, 2px) rotateZ(0deg);
  }

  75% {
    transform: translate(2px, 0px) rotateZ(-1deg);
  }

  100% {
    transform: translate(0px, 0px) rotateZ(0deg);
  }
}

.video__container {
  position: relative;
  width: 100%;
  margin: 0 auto;
  background-color: #000;
  overflow: hidden;
  cursor: pointer;
  aspect-ratio: 16/9;
}

.video__item {
  width: 100%;
  display: block;
  margin: 0 !important;
}

.video__overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 2;
  transition: opacity 0.3s ease;
}

.video__thumbnail {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 1;
}

.video__text {
  color: #fff;
  font-size: 1.5rem;
  font-weight: bold;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.7);
  margin-bottom: 20px;
  z-index: 3;
  pointer-events: none;
}

.video__play-btn {
  width: 80px;
  height: 80px;
  background-color: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 3;
  transition: transform 0.2s ease, background-color 0.2s ease;
}

.video__play-btn:hover {
  transform: scale(1.1);
  background-color: #fff;
}

.video__play-icon {
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 15px 0 15px 25px;
  border-color: transparent transparent transparent #fff;
  margin-left: 5px;
}

.is-playing .video__overlay,
.is-playing .video__thumbnail {
  display: none !important;
}

 .overlap-images {
  font-size: 20px;
}

 .overlap-images .image {
  position: relative;
}

 .overlap-images .image img {
  width: 100%;
  height: auto;
  max-width: unset
}

 .overlap-images .image:nth-child(1) {
  z-index: 10;
}

 .overlap-images .image:nth-child(2) {
  z-index: 0;
  margin-top: -10em;
}


@media (max-width: 500px) {
   .overlap-images .image:nth-child(2) {
    margin-top: -6em;
  }
}

.bg-container {
  font-size: 16px;
  width: min(750px, 100%);
  aspect-ratio: 750/647;
  margin-inline: auto;
  box-sizing: border-box;
  background: no-repeat center/cover;
  background-image: url('/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png');
}

.bg-images-field {
  position: relative;
  width: 100%;
  aspect-ratio: 750/647;
}

.bg-images-field .image {
  width: 35%;
  position: absolute;
}

.bg-images-field .image img {
  width: 100%;
  height: auto;
}

.bg-images-field .image:first-of-type {
  top: 33%;
  left: 5%;
}

.bg-images-field .image:nth-of-type(2) {
  top: 50%;
  right: 1%;
}

.bg-images-field .image:nth-of-type(3) {
  bottom: 0;
  left: 1%;
}

.bg-container * {
  box-sizing: border-box;
}

.js-scroll-target {
  opacity: 0;
}

.js-scroll-target.is-show {
  animation: bgContainerFadeIn 0.5s ease-in-out forwards;
  animation-delay: var(--delay, 0s);
}

@keyframes bgContainerFadeIn {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.EDITABLE .js-scroll-target {
  opacity: 1;
}

 .bg-container {
  font-size: 16px;
  width: min(750px, 100%);
  margin-inline: auto;
  padding: 3em 1em;
  box-sizing: border-box;
  background: no-repeat center/cover;
  background-image: url('/uploads/8bc3b481e7ceeecd3db7f350f82b9538ac6b5d5194e9e927f8c0fa909b6f6f40.png');
}

 .bg-container-title {
  width: 100%;
  text-align: center;
  margin-bottom: 2em;
}

 .bg-container-title img {
  width: 100%;
}

 .bg-container-title:not(:has(img)) {
  font-size: 1.5em;
  font-weight: 600;
  line-height: 1.35;
}

 .bg-images-field {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1em;
}

 .bg-images-field .image {
  width: calc(100% / 3 - 0.75em);
}

 .bg-images-field .image img {
  width: 100%;
  height: auto;
}

 .bg-container * {
  box-sizing: border-box;
}


.js-scroll-target {
  opacity: 0;
}

.js-scroll-target.is-show {
  animation: bgContainerFadeIn 0.5s ease-in-out forwards;
  animation-delay: var(--delay, 0s);
}

@keyframes bgContainerFadeIn {
  from {
    opacity: 0;
    transform: translateY(15px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}



.EDITABLE .js-scroll-target {
  opacity: 1;
}

.fuwafuwa {
  animation: fuwafuwa 3s ease-in-out infinite alternate;
  display: inline-block;
  width: 70px;
  margin-top: 15px;
}

@keyframes fuwafuwa {
  0% {
    transform: translate(0, 0) rotate(-7deg);
  }

  50% {
    transform: translate(0, -7px) rotate(0deg);
  }

  100% {
    transform: translate(0, 0) rotate(7deg);
  }
}

.slideItem__area {
  width: 100%;
  height: auto;
  overflow: hidden;
  position: relative;
}

.slideItem__area img {
  width: 100%;
  height: auto;
}

.slideItem__area picture:nth-of-type(2) img,
.slideItem__area a picture img {
  position: absolute;
  top: 0;
  transform: translateX(70%);
  opacity: 0;
  display: none;
}

.slideItem__area.is-visible picture:nth-of-type(2) img,
.slideItem__area.is-visible a picture img {
  display: block;
  animation: slideItem 0.8s forwards 1;
}

@keyframes slideItem {
  0% {
    transform: translateX(70%);
    opacity: 0;
  }

  100% {
    transform: translateX(0);
    opacity: 1;
  }
}

.slideItem__area a {
  display: none;
}

.slideItem__area.is-visible a {
  width: 100%;
  height: auto;
  display: block;
  cursor: pointer;
}

 .swiper-container {
  font-size: 16px;
  margin: 0 auto;
  position: relative;
}



.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
}

 .swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

 .swiper-slide {
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
}

 .btn-download {
  text-decoration: none !important;
  color: #333;
  display: block;
  text-align: center;
  margin: 10px auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 0.875em;
}

 .btn-download::before {
  content: '';
  display: block;
  width: 1em;
  aspect-ratio: 1;
  background-color: currentColor;
  mask: url('/uploads/637482f8ecb8d371558eff13ac557409b14a10e3c0b2d6bc8a6e282367eafabc.svg') no-repeat center center / contain;
}



.swiper-slide img {
  width: 100%;
}

 .swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}



.swiper-button-next,
 .swiper-button-prev {
  position: absolute;
  top: 50%;
  translate: 0 -50%;
  cursor: pointer;
  outline: none;
}



.swiper-button-next {
  right: -15px;
  left: auto;
}



.swiper-button-prev {
  left: -15px;
  right: auto;
}

 .swiper-button-prev,
 .swiper-button-next {
  background-color: #0f34b1;
  width: 30px;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
}



.swiper-button-next::before,
 .swiper-button-prev::before {
  content: '';
  display: block;
  width: 6px;
  aspect-ratio: 3/4;
  clip-path: polygon(0 0, 0% 100%, 100% 50%);
  background-color: #FFF;
}

 .swiper-button-prev::before {
  transform: rotate(180deg);
}

 .swiper-pagination {
  display: flex;
  gap: 10px;
  justify-content: center;
  align-items: center;
  margin-top: 10px;
}

 .swiper-pagination-bullet {
  background-color: #0f34b194;
  display: block;
  width: 10px;
  aspect-ratio: 1;
  border-radius: 50%;
  opacity: 1;
}

 .swiper-pagination-bullet-active {
  background-color: #0f34b1;
}

@media (max-width: 500px) {
   .btn-download {
    font-size: 1em;
  }
}

 .EDITOR_STYLE .swiper {
  position: relative;
  overflow: unset;
}

 .EDITOR_STYLE .swiper-wrapper {
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
}

 .EDITOR_STYLE .swiper-slide {
  width: fit-content;
  margin: 0 10px;
  scroll-snap-align: start;
}

img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.imgIntroduct__area {
  width: 100%;
  height: auto;
  position: relative;
  font-size: min(3vw, 16px);
}

.imgIntroduct--head__box {
  width: 100%;
  height: auto;
  aspect-ratio: 800/533;
  background-image: url(/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png);
  background-repeat: no-repeat;
  background-size: contain;
  position: relative;
}

.imgIntroduct--head__box img {
  width: 60%;
  height: auto;
  margin: 0 auto;
  position: absolute;
  top: 1em;
  left: 50%;
  transform: translateX(-50%);
}

.imgIntroduct--content__box {
  width: 100%;
  height: auto;
  margin-top: -4em;
}

.imgIntroduct--foot__box {
  width: 100%;
  height: auto;
  margin-top: -2em;
  padding-bottom: 1em;
  position: relative;
  z-index: 2;
  background: linear-gradient(180deg, rgba(210, 242, 250, 0) 0%, rgba(210, 242, 250, 1) 10%, rgba(210, 242, 250, 1) 100%);
}

.imgIntroduct--foot__inner {
  width: 100%;
  height: auto;
  aspect-ratio: 800/533;
  background-image: url(/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png);
  background-size: 80%;
  background-repeat: no-repeat;
  background-position: top center;
  position: relative;
  text-align: center;
}

.imgIntroduct--foot__inner .en {
  display: inline-block;
  font-family: "Snell Roundhand", "Segoe Script", cursive;
  transform: rotate(-15deg) translateX(-0.2em);
  font-size: 1.2em;
}

.imgIntroduct--foot__inner .leftText {
  position: absolute;
  top: 1em;
  left: 6em;
  color: #F3C759;
  font-size: 1.5em;
  font-weight: bold;
}

.imgIntroduct--foot__inner .rightText {
  position: absolute;
  top: 1em;
  right: 6em;
  color: #45A1CF;
  font-size: 1.5em;
  font-weight: bold;
}

@media screen and (max-width: 600px) {
  .imgIntroduct--foot__inner .leftText {
    left: 4.5em;
  }

  .imgIntroduct--foot__inner .rightText {
    right: 4.5em;
  }
}

img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.imgPlacement__box {
  width: 100%;
  height: auto;
  aspect-ratio: 1/1;
  background: #ececec;
  position: relative;
  font-size: min(3vw, 16px);
}

.imgPlacement__box .imgPlacement--item__box:first-of-type {
  width: 80%;
  height: auto;
  position: absolute;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
  z-index: 2;
}

.imgPlacement__box .imgPlacement--item__box:nth-of-type(2) {
  width: 30%;
  height: auto;
  position: absolute;
  top: 0;
  right: 1em;
  z-index: 1;
}

img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.templateKV__area {
  width: 100%;
  height: auto;
  aspect-ratio: 1/1;
  margin-bottom: 7em;
  background-image: url(/uploads/a4ad660fa35ff5bbd7bfc5e9eb29a3b460b3e28e4ccf951785eb91456b55f904.png);
  background-repeat: no-repeat;
  background-size: contain;
  position: relative;
  font-size: min(3vw, 16px);
}

