  line-height: 0;
}

/* 画像 */
.imgItem img {
  /* 横幅 */
  width: 100%;
  /*　---画像をトリミングして表示する場合は以下を使用してください---　*/
  /* 高さ */
  height: 200px !important;
  /* 画像を囲ってる箱に合わせて画像を表示する。
      cover=アスペクト比を維持したまま、高さまたは幅にあわせて拡大縮小して切り取る
      contain=アスペクト比を維持したまま、高さまたは幅に合わせて拡大縮小し収める） */
  object-fit: cover;
  /* 切り取る位置｜X方向｜Y方向｜ */
  object-position: 50% 0;
