  background-color: #ffffff;
  top: 0;
  bottom: 0;
  left: calc(50% - 1px);
  z-index: 5;
}

.compare-slider .compare-container .compare-control::before,
.compare-slider .compare-container .compare-control::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 10px;
  border: 10px solid transparent;
  box-sizing: border-box;
}

.compare-slider .compare-container .compare-control::before {
  /* 右三角 */
  border-right: 10px solid #ffffff;
  top: calc(50% - 5px);
  right: 1px;
  transition: right 0.1s;
}

.compare-slider .compare-container .compare-control::after {
  /* 左三角 */
  border-left: 10px solid #ffffff;
  top: calc(50% - 5px);
  left: 1px;
  transition: left 0.1s;
}

.compare-slider .compare-container:active .compare-control::before,
.compare-slider .compare-container:hover .compare-control::before {
  right: 8px;
}

.compare-slider .compare-container:active .compare-control::after,
.compare-slider .compare-container:hover .compare-control::after {
  left: 8px;
}

