/* スクラッチを囲ってる箱 */
.scratch__area {
  /* 横幅 */
  width: 600px;
  /* 最大幅 */
  max-width: 100%;
  /* 子要素の高さを反映 */
  min-height: initial !important;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 20px auto 0;
  position: relative;
  aspect-ratio: 200 / 133;
}

.scratch__area a {
  display: block;
  /* 横幅 */
  width: 100%;
  /* 最大幅（スクラッチ画像の横幅と同じにしてください） */
  max-width: 400px;
  /* 高さ */
  height: auto;
  position: absolute;
  top: 0;
  /* センタリング */
  left: 50%;
  transform: translateX(-50%);
}



/* スクラッチ */
.scratch__content {
  /* 横幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 400px;
  /* 高さ */
  height: 100%;
  display: flex;
  /*水平方向に間隔を配置する方法。（canvasタグに配慮）
    flex-start = 左側から配置する
    flex-end = 右側から配置する
    center = 真ん中に配置する
    space-around = 均等配置して両端に間隔を置く
    space-between = 均等配置してエリアの間に間隔を置く
    space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  margin: 0 auto;
}



/* スクラッチの画像と削る部分 */
.scratch__content>div {
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
  /* 画像の大きさ */
  background-size: 100%;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #000;
  display: inline-block;
  /* はみ出たものを隠す */
  overflow: hidden;
  /* スクラッチ画像をリピートさせない */
  background-repeat: no-repeat;
}

/* レスポンシブ設定（virsion設定→配信virsion幅の大きさに合わせて「600px」部分を変更してください） */
