    /* 高さ */
    height: auto !important;
    /* スクラッチ画像の比率（横 / 縦） */
    aspect-ratio: 200 / 133;
  }



  /* スクラッチの削るレイヤー */
  .scratch__content>div>canvas {
    /* スクラッチ画像の比率と同じにしてください（横 / 縦） */
    aspect-ratio: 200 / 133 !important;
    width: 100%;
    height: 100% !important;
  }

  .scratch__area {
    aspect-ratio: 200 / 133;
  }
}

/* レスポンシブ設定（virsion設定→配信virsion幅の大きさに合わせて「600px」部分を変更してください） */
