  width: 70vw;
  /*背景色*/
  background-color: #efefef;
  /*画面全体への影の指定。水平方向の距離｜垂直方向の距離｜ぼかし距離｜広がり距離｜影の色。
   rgba色は r=Red、g=Green、b=Blue、a=Alpha透明度。rgbは0から255まで。aは0から1まで。*/
  box-shadow: 0 0 0 9999px rgba(0, 0, 0, .8);
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  margin: auto;
  height: fit-content;
  overflow-y: scroll;
  z-index: 11111111111111111111;
}



/* チェックボックスの初期設定 */
