.couponFixed__area .myCoupon__area .myCoupon__text {
  /* 文字の大きさ */
  font-size: 18px;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の色 */
  color: #fff;
  /* 外側の余白｜上余白｜左右余白｜下余白｜ */
  margin: 0 0 30px;
  /* 文字寄せ */
  text-align: center;
}



/* ダミーイメージ */
