  /* 高さ */
  height: auto;
}



/*widgetエリア*/
.couponFixed__area .todaysCoupon__area {
  /* 領域内はカーソルがポインターになる */
  cursor: pointer;
}



/* クーポン画像が入ってるエリア */
.couponFixed__area .myCoupon__area .couponImg__box {
  /* widget全体の90%の横幅 */
  width: 90%;
  /* 外側の余白｜上余白｜左右余白（auto=センタリング）｜下余白｜*/
  margin: 0 auto 20px;
}



/* クーポン画像のリンク */
.couponFixed__area .myCoupon__area .couponImg__box a {
  display: block;
  /* 下外側余白 */
  margin-bottom: 3px;
  /* hover時の変化時間 */
  transition: all 0.2s;
  /* 変形｜-10度傾ける｜ */
  transform: rotate(-10deg);
}



/* クーポン画像hover時 */
.couponFixed__area .myCoupon__area .couponImg__box a:hover {
  /* 透明度 */
  opacity: 0.8;
}



/* 水色のクーポン画像部分 */
.couponFixed__area .myCoupon__area .couponImg__box a:first-of-type {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜アニメーションの実行前後の状態｜*/
  animation: coupon1st 2s ease-in 1 backwards;
}



/* 黄色のクーポン画像部分 */
.couponFixed__area .myCoupon__area .couponImg__box a:nth-of-type(2) {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜アニメーションの実行前後の状態｜*/
  animation: coupon2nd 2s ease-in 1 backwards;
}



/* ピンクのクーポン画像部分 */
.couponFixed__area .myCoupon__area .couponImg__box a:last-of-type {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜アニメーションの実行前後の状態｜*/
  animation: coupon3rd 2s ease-in 1 backwards;
}



/* widgetが表示領域に入った時 */
.is-active {
  display: block;
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜*/
  animation: fadein 1s;
  /* 表示する順番（レイヤー） */
  z-index: 1001;
}



/* 今日のクーポンエリア表示時 */
.is-nonFade-active {
  display: block;
}



/* 今日のクーポンエリア内のクーポン画像エリア表示時 */
.is-nonFade-active .couponImg__box {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜アニメーションの実行前後の状態｜*/
  animation: slideUp 0.5s ease-in 0.8s 1 backwards;
}



/* 非表示部分に付与 */
.is-inactive {
  display: none;
  /* 表示する順番（レイヤー） */
  z-index: 1000;
}

/* widgetが表示領域に入った時のアニメーション */
@keyframes fadein {

  /* 最初 */
  0% {
    /* 透明度 */
    opacity: 0;
  }

  /* 最後 */
  100% {
    opacity: 1;
  }
}

/* 非表示になった時のアニメーション */
@keyframes fadeOut {

  /* 最初 */
  0% {
    /* 透明度 */
    opacity: 1;
  }

  /* 最後 */
  100% {
    opacity: 0;
  }
}

/* 今日のクーポン表示時の画像エリアのアニメーション */
@keyframes slideUp {
  0% {
    /* 高さ */
    height: 0;
  }

  100% {
    /* クーポン画像を変更時に適宜変更してください */
    height: 247px;
  }
}

/* 水色クーポン画像のアニメーション */
@keyframes coupon1st {
  0% {
    /* 透明度 */
    opacity: 0;
    /* 変形｜大きさ（倍率）｜回転角度｜位置（X, Y）｜ */
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }

  69% {
    opacity: 0;
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }

  70% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }

  100% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }
}

/* 黄色クーポン画像のアニメーション */
@keyframes coupon2nd {
  0% {
    opacity: 0;
    transform: scale(1) rotate(-10deg) translate(15px, -82px);
  }

  69% {
    opacity: 0;
    transform: scale(1) rotate(-10deg) translate(15px, -82px);
  }

  70% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(15px, -83px);
  }

  100% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }
}

/* ピンククーポン画像のアニメーション */
@keyframes coupon3rd {
  0% {
    opacity: 0;
    transform: scale(0) rotate(-10deg) translate(20px, -120px);
  }

  25% {
    opacity: 0.75;
    transform: scale(0) rotate(-10deg) translate(20px, -120px);
  }

  44%,
  55% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(20px, -120px);
  }

  70% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(29px, -167px);
  }

  100% {
    opacity: 1;
    transform: scale(1) rotate(-10deg) translate(0, 0);
  }
}

/* スマホで表示時 */
@media screen and (max-width:767px) {


  /* widget全体 */
  .couponFixed__area {
    /* 変形｜大きさ（倍率）｜位置（X, Y）｜ */
    transform: scale(0.7) translate(10px, 0);
    /* 変形の基準位置 */
    transform-origin: bottom right;
  }
}

