.purupuru {
  /*アニメーション名、動きの速さ0.8s（=0.8秒）、動き具合、開始時間5s(=5秒後)、動く回数infinite(=無限 3=3回など)   */
  animation: purupuru 2s linear 0s infinite;
}

@keyframes purupuru {

  /*アニメーションの最初の動き*/
  0% {
    /*skew = 傾斜変形する、1番目の値はX軸、2番目に値がある場合はY軸に傾斜変形する
   　　　　9deg = 9度*/
    transform: skew(9deg);
  }

  10% {
    transform: skew(-8deg);
  }

  20% {
    transform: skew(7deg);
  }

  30% {
    transform: skew(-6deg);
  }

  40% {
    transform: skew(5deg);
  }

  50% {
    transform: skew(-4deg);
  }

  60% {
    transform: skew(3deg);
  }

  70% {
    transform: skew(-2deg);
  }

  80% {
    transform: skew(1deg);
  }

  90% {
    transform: skew(0deg);
  }

  /*アニメーションの最後の動き*/
  100% {
    transform: skew(0deg);
  }
}

